using namespace std;

void PrintStack(stack<char> s) {
    if (s.empty()) return;                     // empty stack → nothing to print
    const char x = s.top();                    // current top element
    s.pop();                                    // remove it
    PrintStack(s);                             // recurse on the reduced stack
    cout << x;                                 // output the popped element
    s.push(x);                                 // restore the element for the next iteration
}

void minString(string s) {
    stack<char> Stack;
    Stack.push(s[0]);                           // start with the first character

    for (size_t i = 1; i < s.size(); ++i) {    // process remaining characters
        if (Stack.empty()) {
            Stack.push(s[i]);                  // first character becomes the candidate
        } else {
            if (Stack.top() == s[i]) {
                Stack.pop();                    // duplicate → discard
            } else {
                Stack.push(s[i]);              // different character → keep
            }
        }
    }

    PrintStack(Stack);                          // output the minimal string
}

