    // Base case: the first element of the first level is always 'e'.
    if (level == 1) return 'e';

    // Recursively obtain the element at the parent level.
    const char parent = findProffesion(level - 1, (pos + 1) / 2);

    // Determine the current element's character based on parity.
    return (pos % 2) ? parent : 'd';
}

