int gcd(int a, int b) {
    // Euclidean algorithm; handles zero input gracefully.
    while (b != 0) {
        int r = a % b;
        a = b;
        b = r;
    }
    return a;
}

int CountPairs(int n) {
    int cnt = 0;
    // Use a 64‑bit loop to avoid overflow for large n.
    for (long long i = 1; i * i <= n; ++i) {
        if (n % i == 0) {
            const long long div1 = i;
            const long long div2 = n / i;
            const long long sum = div1 + div2;
            // gcd of sum and n must be 1 for a valid pair.
            if (gcd(static_cast<int>(sum), static_cast<int>(n)) == 1) {
                ++cnt;
            }
        }
    }
    return cnt;
}

