int CountPairs(int n) {
    int cnt = 0;
    // Use a stack to preserve the order of divisor pairs.
    stack<pair<int,int>> divisors;
    divisors.emplace(1, n);

    while (!divisors.empty()) {
        auto [div1, div2] = divisors.top();
        divisors.pop();

        int sum = div1 + div2;
        if (gcd(sum, n) == 1) {
            ++cnt;
        }

        // Push the complementary divisor pair.
        divisors.emplace(div2, div1);
