Error_code parameterize(Triangle_mesh& tmesh,
                        halfedge_descriptor bhd,
                        VertexUVmap uvmap,
                        VertexIndexMap vimap,
                        VertexParameterizedMap vpmap,
                        unsigned int& iterations)
{
    // Use a std::stack for the call‑stack-like behavior.
    std::stack<halfedge_descriptor> stack;
    stack.push(bhd);

    while (!stack.empty()) {
        halfedge_descriptor hd = stack.top();
        stack.pop();

        // Forward to the recursive overload that records errors.
        Error_code err = parameterize(tmesh, hd, uvmap, vimap, vpmap, iterations, unused_error);
        if (err != Error_code::SUCCESS) {
            return err; // Propagate first error encountered.
        }
    }

    return Error_code::SUCCESS; // All iterations succeeded.
}

