      if (i == N - 1)
      {
        ans += to_string(count);
        ans += prev_ans[i];
      }
      else if (prev_ans[i] == prev_ans[i + 1])
        count++;
      else
      {
        ans += to_string(count);
        ans += prev_ans[i];
        count = 1;
      }
    }

    return ans;
  }

