    if (s.empty()) return;                     // base case: no more characters to explore

    if (st.find(s) == st.end()) {              // avoid duplicates
        st.insert(s);

        // use a std::stack for deterministic order; std::queue would be FIFO
        std::stack<char> stack;
        stack.push(s.front());
        s.erase(0, 1);                         // remove the first character

        while (!stack.empty()) {
            char ch = stack.top();
            stack.pop();

            for (size_t i = 0; i < s.size(); ++i) {
                string t = s;
                t.erase(i, 1);                 // remove the i‑th character
                generate(st, t);               // recurse with the reduced string
            }
        }
    }
}

