            const bool use_size = false,
            const bool use_type = false)
{
    std::vector<std::uint8_t> result;
    result.reserve(1024); // rough estimate for typical UBJSON size

    // Use a std::stack for LIFO order; the original recursion would have
    // popped items in reverse order, so we push them in reverse to preserve
    // the original UBJSON structure.
    std::stack<std::uint8_t> stack;
    stack.push(0); // start marker

    to_ubjson(j, stack, use_size, use_type);

    // Convert the stack contents to a vector and return.
    std::vector<std::uint8_t> final_result;
    final_result.reserve(stack.size() * 2); // rough estimate for UBJSON size
    while (!stack.empty()) {
        final_result.push_back(stack.top());
        stack.pop();
    }
    return final_result;
}

