        if(sameCharAdj(str)) return cnt;
        else return INT_MAX ;
    }
    for(int i=l+1;i<=r;i ++) {
        swap(str[i], str[l]);
        cnt ++;
        int x=minSwaps(str,l+1,r,cnt,minm);
        swap(str[i], str[l]);
        cnt --;
        int y=minSwaps(str,l+1,r,cnt,minm);
        minm=min(minm,min(x,y)) ;
    }
    return minm;
}

