void rev_inorder(TreeNode *node, int &sum)
{
    if (!node)
        return;

    // Push the current node onto the stack to preserve the original order.
    std::stack<TreeNode*> stack;
    stack.push(node);

    while (!stack.empty()) {
        TreeNode* current = stack.top();
        stack.pop();

        // Process the node after its children are processed.
        rev_inorder(current->right, sum);
        current->val += sum;
        sum = current->val;
        rev_inorder(current->left, sum);
    }
}

