bool isCompleteTree(TreeNode* root) {
    if (!root) return true;

    // Use std::stack for explicit control over the call stack.
    std::stack<TreeNode*> s;
    s.push(root);

    // Count nodes in the left subtree.
    int left = 0;
    while (!s.empty()) {
        TreeNode* cur = s.top();
        s.pop();
        if (cur->left) {
            ++left;
            s.push(cur->left);
        }
        if (cur->right) {
            ++left;
            s.push(cur->right);
        }
    }

    // Count nodes in the right subtree.
    int right = 0;
    s.push(root);
    while (!s.empty()) {
        TreeNode* cur = s.top();
        s.pop();
        if (cur->left) {
            ++right;
            s.push(cur->left);
        }
        if (cur->right) {
            ++right;
            s.push(cur->right);
        }
    }

    // Left subtree must be fully populated.
    if (left < right) return false;

    // If left and right are equal, both subtrees must be full.
    if (left == right) {
        return isFullTree(root->left, left - 1) && isFullTree(root->right, right - 1);
