void findMaxDiff(TreeNode* root) {
    if (!root || !root->left && !root->right)
        return;

    // Use std::stack for explicit control over the call stack.
    std::stack<TreeNode*> s;
    s.push(root);

    while (!s.empty()) {
        TreeNode* node = s.top();
        s.pop();

        // Compute max differences for this node.
        findMaxUtil(node, node->left);
        findMaxUtil(node, node->right);

        // Push children onto the stack in reverse order to preserve original traversal order.
        if (node->right)
            s.push(node->right);
        if (node->left)
            s.push(node->left);
    }
}

