void findMaxDiff(TreeNode* root) {
    if (!root || !root->left && !root->right)
        return;

    // Use a stack for depth‑first traversal; the stack holds nodes in reverse order
    std::stack<TreeNode*> pending;
    pending.push(root);

    while (!pending.empty()) {
        TreeNode* c = pending.top(); pending.pop();

        // Compute max difference for this node with its left child
        findMaxUtil(c, c->left);

        // Push right child first so it is processed before left child
        if (c->right) {
            pending.push(c->right);
        }
        if (c->left) {
            pending.push(c->left);
        }
    }
}

