    // First column
    if (j == 0)
        return dp[i][j] = triangle[i][j] + go(triangle, i - 1, 0, dp);

    // Last column
    if (j == i)
        return dp[i][j] = triangle[i][j] + go(triangle, i - 1, i - 1, dp);

    // General interior cell
    const int left  = go(triangle, i - 1, j - 1, dp);
    const int right = go(triangle, i - 1, j, dp);
    return dp[i][j] = triangle[i][j] + std::min(left, right);
