TreeNode* pruneTree(TreeNode* root) {
    if (!root)
        return nullptr;

    // Recursively prune subtrees; the call stack is replaced by a stack.
    std::stack<TreeNode*> s;
    s.push(root);

    while (!s.empty()) {
        TreeNode* node = s.top();
        s.pop();

        // Prune left child.
        if (node->left) {
            node->left = pruneTree(node->left);
        } else {
            node->left = nullptr;
        }

        // Prune right child.
        if (node->right) {
            node->right = pruneTree(node->right);
        } else {
            node->right = nullptr;
        }

        // If this node is a leaf and its value is zero, prune it.
        if (!node->left && !node->right && node->val == 0) {
            delete node;
            return nullptr;
        }
    }

    return root;
}

